51	  PREV_CHUNK_SIZE,
52	  CHUNK_SIZE,
53	  CHUNK_EXTENSION,
54	  PREV_CHUNK_SIZE_LF,
55	  CHUNK,
56	  PREV_CHUNK_CR,
57	  PREV_CHUNK_LF,
58	  PREV_TRAILER,
59	  TRAILER,
60	  PREV_TRAILER_LF,
61	  PREV_END_CR,
62	  PREV_END_LF,
63	  CHUNKS_COMPLETE
64	};
65	} // namespace
