68	    std::unique_ptr<StreamFilter> delegate)
69	    : StreamFilter{std::move(delegate)},
70	      state_{PREV_CHUNK_SIZE},
71	      chunkSize_{0},
72	      chunkRemaining_{0},
73	      bytesProcessed_{0}
74	{
75	}
76	
77	ChunkedDecodingStreamFilter::~ChunkedDecodingStreamFilter() = default;
78	
79	void ChunkedDecodingStreamFilter::init() {}
