81	ssize_t
82	ChunkedDecodingStreamFilter::transform(const std::shared_ptr<BinaryStream>& out,
83	                                       const std::shared_ptr<Segment>& segment,
84	                                       const unsigned char* inbuf, size_t inlen)
85	{
86	  ssize_t outlen = 0;
87	  size_t i;
88	  bytesProcessed_ = 0;
89	  for (i = 0; i < inlen; ++i) {
90	    unsigned char c = inbuf[i];
91	    switch (state_) {
92	    case PREV_CHUNK_SIZE:
93	      if (util::isHexDigit(c)) {
94	        chunkSize_ = util::hexCharToUInt(c);
95	        state_ = CHUNK_SIZE;
96	      }
97	      else {
98	        throw DL_ABORT_EX("Bad chunk size: not hex string");
99	      }
100	      break;
101	    case CHUNK_SIZE:
102	      if (util::isHexDigit(c)) {
103	        if (chunkSize_ & 0x7800000000000000LL) {
104	          throw DL_ABORT_EX("Too big chunk size");
105	        }
106	        chunkSize_ <<= 4;
107	        chunkSize_ += util::hexCharToUInt(c);
108	      }
109	      else if (c == ';') {
110	        state_ = CHUNK_EXTENSION;
111	      }
112	      else if (c == '\r') {
113	        state_ = PREV_CHUNK_SIZE_LF;
114	      }
115	      else {
116	        throw DL_ABORT_EX("Bad chunk size: not hex string");
117	      }
118	      break;
119	    case CHUNK_EXTENSION:
120	      if (c == '\r') {
121	        state_ = PREV_CHUNK_SIZE_LF;
122	      }
123	      break;
124	    case PREV_CHUNK_SIZE_LF:
125	      if (c == '\n') {
126	        chunkRemaining_ = chunkSize_;
127	        if (chunkSize_ == 0) {
128	          state_ = PREV_TRAILER;
129	        }
130	        else {
131	          state_ = CHUNK;
132	        }
133	      }
134	      else {
135	        throw DL_ABORT_EX("Bad chunk encoding: "
136	                          "missing LF at the end of chunk size");
137	      }
138	      break;
139	    case CHUNK: {
140	      int64_t readlen =
141	          std::min(chunkRemaining_, static_cast<int64_t>(inlen - i));
142	      outlen += getDelegate()->transform(out, segment, inbuf + i, readlen);
143	      chunkRemaining_ -= readlen;
144	      i += readlen - 1;
145	      if (chunkRemaining_ == 0) {
146	        state_ = PREV_CHUNK_CR;
147	      }
148	      break;
149	    }
150	    case PREV_CHUNK_CR:
151	      if (c == '\r') {
152	        state_ = PREV_CHUNK_LF;
153	      }
154	      else {
155	        throw DL_ABORT_EX("Bad chunk encoding: "
156	                          "missing CR at the end of chunk");
157	      }
158	      break;
159	    case PREV_CHUNK_LF:
160	      if (c == '\n') {
161	        if (chunkSize_ == 0) {
162	          state_ = PREV_TRAILER;
163	        }
164	        else {
165	          chunkSize_ = chunkRemaining_ = 0;
166	          state_ = PREV_CHUNK_SIZE;
167	        }
168	      }
169	      else {
170	        throw DL_ABORT_EX("Bad chunk encoding: "
171	                          "missing LF at the end of chunk");
172	      }
173	      break;
174	    case PREV_TRAILER:
175	      if (c == '\r') {
176	        // No trailer
177	        state_ = PREV_END_LF;
178	      }
179	      else {
180	        state_ = TRAILER;
181	      }
182	      break;
183	    case TRAILER:
184	      if (c == '\r') {
185	        state_ = PREV_TRAILER_LF;
186	      }
187	      break;
188	    case PREV_TRAILER_LF:
189	      if (c == '\n') {
190	        state_ = PREV_TRAILER;
191	      }
192	      else {
193	        throw DL_ABORT_EX("Bad chunk encoding: "
194	                          "missing LF at the end of trailer");
195	      }
196	      break;
197	    case PREV_END_LF:
198	      if (c == '\n') {
199	        state_ = CHUNKS_COMPLETE;
200	      }
201	      else {
202	        throw DL_ABORT_EX("Bad chunk encoding: "
203	                          "missing LF at the end of chunks");
204	      }
205	      break;
206	    case CHUNKS_COMPLETE:
207	      goto fin;
208	    default:
209	      // unreachable
210	      assert(0);
211	    }
212	  }
213	fin:
214	  bytesProcessed_ += i;
215	  return outlen;
216	}
