164	        else {
165	          chunkSize_ = chunkRemaining_ = 0;
166	          state_ = PREV_CHUNK_SIZE;
167	        }
168	      }
169	      else {
170	        throw DL_ABORT_EX("Bad chunk encoding: "
171	                          "missing LF at the end of chunk");
172	      }
173	      break;
174	    case PREV_TRAILER:
175	      if (c == '\r') {
176	        // No trailer
177	        state_ = PREV_END_LF;
178	      }
179	      else {
180	        state_ = TRAILER;
181	      }
182	      break;
183	    case TRAILER:
184	      if (c == '\r') {
185	        state_ = PREV_TRAILER_LF;
186	      }
187	      break;
188	    case PREV_TRAILER_LF:
189	      if (c == '\n') {
190	        state_ = PREV_TRAILER;
191	      }
192	      else {
193	        throw DL_ABORT_EX("Bad chunk encoding: "
194	                          "missing LF at the end of trailer");
195	      }
196	      break;
197	    case PREV_END_LF:
198	      if (c == '\n') {
199	        state_ = CHUNKS_COMPLETE;
200	      }
201	      else {
202	        throw DL_ABORT_EX("Bad chunk encoding: "
203	                          "missing LF at the end of chunks");
204	      }
205	      break;
206	    case CHUNKS_COMPLETE:
207	      goto fin;
208	    default:
209	      // unreachable
210	      assert(0);
211	    }
212	  }
213	fin:
214	  bytesProcessed_ += i;
215	  return outlen;
216	}
217	
218	bool ChunkedDecodingStreamFilter::finished()
219	{
220	  return state_ == CHUNKS_COMPLETE && getDelegate()->finished();
221	}
222	
223	void ChunkedDecodingStreamFilter::release() {}
224	
225	const std::string& ChunkedDecodingStreamFilter::getName() const { return NAME; }
226	
