488	bool HttpResponseCommand::skipResponseBody(
489	    std::unique_ptr<HttpResponse> httpResponse)
490	{
491	  auto filter = getTransferEncodingStreamFilter(httpResponse.get());
492	  // We don't use Content-Encoding here because this response body is just
493	  // thrown away.
494	  auto httpResponsePtr = httpResponse.get();
495	  auto command = make_unique<HttpSkipResponseCommand>(
496	      getCuid(), getRequest(), getFileEntry(), getRequestGroup(),
497	      httpConnection_, std::move(httpResponse), getDownloadEngine(),
498	      getSocket());
499	  command->installStreamFilter(std::move(filter));
500	
501	  // If request method is HEAD or the response body is zero-length,
502	  // set command's status to real time so that avoid read check blocking
503	  if (getRequest()->getMethod() == Request::METHOD_HEAD ||
504	      (httpResponsePtr->getEntityLength() == 0 &&
505	       !httpResponsePtr->isTransferEncodingSpecified())) {
506	    command->setStatusRealtime();
507	    // If entity length == 0, then socket read/write check must be disabled.
508	    command->disableSocketCheck();
509	    getDownloadEngine()->setNoWait(true);
510	  }
511	
512	  getDownloadEngine()->addCommand(std::move(command));
513	  return true;
514	}
