518	bool decideFileAllocation(StreamFilter* filter)
519	{
520	#ifdef HAVE_ZLIB
521	  for (StreamFilter* f = filter; f; f = f->getDelegate().get()) {
522	    // Since the compressed file's length are returned in the response header
523	    // and the decompressed file size is unknown at this point, disable file
524	    // allocation here.
525	    if (f->getName() == GZipDecodingStreamFilter::NAME) {
526	      return false;
527	    }
528	  }
529	#endif // HAVE_ZLIB
530	
531	  return true;
532	}
